import { copyToClipboard } from 'quasar';
import { notify } from 'src/components/notifications/notify';
import { useLoadingStore } from 'src/store/loading.store';
export default {
  methods: {
    toggleMenu() {
      let toggleMenuBtn = document.getElementById('menu_btn');

      if (toggleMenuBtn) {
        let toggleIcon = toggleMenuBtn.querySelector('i').innerHTML;

        if (toggleIcon === 'chevron_left') {
          toggleMenuBtn.querySelector('i').innerHTML = 'chevron_right';
        } else {
          toggleMenuBtn.querySelector('i').innerHTML = 'chevron_left';
        }
      }

      document.getElementById('left_section').classList.toggle('hidden');

      document
        .getElementById('right_section')
        .classList.toggle('right_section');
      document.getElementById('right_section').classList.toggle('full-width');
    },
    showLoading(message) {
      useLoadingStore().beginEpisode(message ?? null);
    },
    hideLoading() {
      useLoadingStore().endEpisode();
    },
    goFormular() {
      window.open('https://cloudintegration.eu/formular');
    },

    copyData(data) {
      if (data.trim().length > 0) {
        copyToClipboard(data).then(() => {
          notify.success(this.$t('copied_successfully'));
        });
      }
    },
  },
};
